	public boolean containsValue(T value) {
		return contains((BinaryNode<T>) root, value);
	}

	private boolean contains(BinaryNode<T> node, T value) {
		if (node == null) {
			return false;
		}

		if (value.compareTo(node.value) < 0) {
			return contains(node.getLeft().orElse(null), value);
		} else if (value.compareTo(node.value) > 0) {
			return contains(node.getRight().orElse(null), value);
		} else {
