	public static Map<String, String> getDomainAndPort(String domainName) {
		Map<String, String> map = new HashMap<>();
		String protocol = getProtocol(domainName);
		if (!protocol.isEmpty()) {
			if (protocol.equals(HTTP)) {
				domainName = domainName.substring(7, domainName.length());
			} else if (protocol.equals(HTTPS)) {
				domainName = domainName.substring(8, domainName.length());
			}
		}

		int portIndex = domainName.indexOf(":");
		if (portIndex != -1) {
			map.put("domain", domainName.substring(0, portIndex));
			map.put("port", domainName.substring(portIndex + 1));
		} else {
			map.put("domain", domainName);
			map.put("port", "");
		}
		return map;
	}
}

